import {createHash} from 'node:crypto';
import {readFileSync, writeFileSync, existsSync, mkdirSync, realpathSync} from 'node:fs';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';

// Diagnostic-only G32 ablation. Never an accepted compiler or an R12 plugin.
const ROOT='/Users/ilyagulya/Projects/My/bend';
const OLD='/private/tmp/bend-g33-diagnostics-gSUmym';
const SELF=fileURLToPath(import.meta.url);
const IMAGE=ROOT+'/checkpoints/local2039g32c-full/bootstrap.json.cases/stage-one.js';
const IMAGE_SHA='419710b98ee9e765e677c5a411a1299cb728db23e58b12dfad69141d9d1721c5';
const FULL_OUTPUT='6ea91c1edba906dfae61eabe44377e9ed88102fa6eda73687be152882c20d490';
const MODES=['unchanged','analysis','full'];
const sha=x=>createHash('sha256').update(x).digest('hex');
const hash=p=>sha(readFileSync(p));
const json=p=>JSON.parse(readFileSync(p,'utf8'));
const assert=(x,m)=>{if(!x)throw Error(m);};
const fresh=(p,x)=>writeFileSync(p,x,{flag:'wx'});
const save=(p,x)=>fresh(p,JSON.stringify(x,null,2)+'\n');
const FIXED={
  [IMAGE]:IMAGE_SHA,
  [OLD+'/g32-source.tar']:'3f334965323b12d9424037c67e29f3baa95d8b560b3999afd4c70dd0399ec24b',
  [OLD+'/manifest.json']:'b3f91c3a98296465c5d65b9aa4ae2e7ac68fbb7fb0f1d0496c9638b289526e3d',
  [OLD+'/.g32-src/bend2/selfhost/backend_transport.bend']:'8889717797bcc9757b15af6aead90bc9e510e43ebeac72b4fe7d6738b2b3eaba',
  [OLD+'/.g32-src/checkpoints/emitter_steps_v1.bend']:'55ed71bbae73dc2c1e762bddbabbaed44e42093669afa807a121fb74b6d6605d',
  [ROOT+'/evals/selfhost_throughput.mjs']:'e1685e74d6f425bc20a5afe0d12564e69accf17aaa3ed54d2a89de15115259ca'
};
function verify(pins){for(const [p,h] of Object.entries(pins))assert(realpathSync(p)===p&&hash(p)===h,'Pin drift: '+p);}
function once(s,a,b){assert(s.split(a).length===2,'Unique anchor required: '+a.slice(0,150));return s.replace(a,()=>b);}
function definition(source,key){
  const prefix='$D['+JSON.stringify(key)+']=';
  const rows=source.split('\n').filter(x=>x.startsWith(prefix));
  assert(rows.length===1,'Unique source declaration required: '+key);
  const ids=[...new Set([...rows[0].matchAll(/\$b\d+\(/g)].map(x=>x[0].slice(0,-1)))];
  assert(ids.length===1,'Ambiguous declaration: '+key);
  const start='function '+ids[0]+'(';
  const defs=source.split('\n').filter(x=>x.startsWith(start));
  assert(defs.length===1,'Unique function required: '+key);
  const opener=defs[0].slice(0,defs[0].indexOf('{')+1);
  return {key,id:ids[0],opener,line:defs[0],sha256:sha(defs[0])};
}
const P='emitter_steps_v1.emitter_body_cps_provider_2_';
const J='emitter_steps_v1.emitter_body_cps_provider_9_';
export function instrument(source,context={}){
  const mode=context.mode;
  assert(MODES.includes(mode),'Explicit G32 ablation mode required');
  assert(sha(source)===IMAGE_SHA,'Only authenticated untouched G32 image is supported');
  const sites=[];
  const add=(key,code,signature)=>{
    const d=definition(source,key);
    if(signature)assert(d.opener===`function ${d.id}(${signature}){`,'Signature drift: '+key);
    sites.push({key,id:d.id,originalFunctionSha256:d.sha256,insertion:code});
    source=once(source,d.opener,d.opener+code);
  };
  add(P+'optimize','globalThis.__transportHook.begin($v0);','$v0,$td=0');
  // Existing successful-width match receives both the validation result and exact original Program.
  add('emitter_steps_v1.emitter_match_777',
    'globalThis.__transportHook.widthDone("optimizer",$v0,$v1);'+
    (mode==='unchanged'?'if($v0.$==="emitter_steps_v1.cps_provider_2_WidthsOk")return {$:"emitter_steps_v1.EmitterFinished",box:{$:"emitter_steps_v1.EmitterValue",value:$v1}};':''),
    '$v0,$v1,$td=0');
  // This is the completed plan_program continuation, NOT a synchronous entry return.
  add('emitter_steps_v1.emitter_continuation_771',
    'globalThis.__transportHook.planned($v0);'+
    (mode==='analysis'?'return {$:"emitter_steps_v1.EmitterFinished",box:{$:"emitter_steps_v1.EmitterValue",value:globalThis.__transportHook.original($v1,$v2,$v3,$v4,$v5,$v6)}};':''),
    '$v0,$v1,$v2,$v3,$v4,$v5,$v6,$td=0');
  add(P+'result_widths','globalThis.__transportHook.widthBegin($v0);','$v0,$td=0');
  add(J+'emit_linked','globalThis.__transportHook.backend($v0);','$v0,$v1,$td=0');
  add(J+'emit_checked_widths','globalThis.__transportHook.widthDone("renderer",$v0,$v1);','$v0,$v1,$v2,$v3,$td=0');
  for(const name of ['program_source','js_scalar_program'])add(J+name,`globalThis.__transportHook.mark(${JSON.stringify(name)});`);
  for(const name of ['scan_block','scan_codes','candidate_map','plan_block','producer_build','consumer_make','rewrite_block','rewrite_codes','rewrite_declarations','rename_block']){
    add(P+name,`globalThis.__transportHook.count(${JSON.stringify(name)});`);
  }
  return {source,metadata:{diagnosticOnly:true,accepted:false,mode,originalImage:{path:IMAGE,sha256:IMAGE_SHA},sites,
    analysisBoundary:'Completed plan_program, before rewrite_codes; plan already constructs worker clones',
    preserved:'Both result_widths calls, link/export checks, scheduler, fuel and quantum unchanged',
    changed:'Only unchanged/analysis substitute a successful EmitterFinished at a functional continuation'}};
}

// A structural hash only; never interprets BIR or calls target closures. Sharing is part of the hash.
function fingerprint(root){
  const h=createHash('sha256'),seen=new WeakMap(),stack=[{value:root}];let nodes=0,edges=0;
  while(stack.length){
    const item=stack.pop();
    if(Object.hasOwn(item,'token')){h.update(item.token);continue;}
    const v=item.value,t=typeof v;
    if(v===null||t!=='object'){
      assert(!['function','symbol'].includes(t),'Non-data BIR field');
      h.update(t+':'+(t==='bigint'?v.toString():JSON.stringify(v))+';');continue;
    }
    const old=seen.get(v);if(old!==undefined){h.update('ref:'+old+';');continue;}
    assert(++nodes<=20000000,'BIR fingerprint node cap');seen.set(v,nodes);
    const descriptors=Object.getOwnPropertyDescriptors(v),keys=Object.keys(descriptors).sort();
    h.update('obj:'+nodes+':'+keys.length+'{');stack.push({token:'}'});
    for(let i=keys.length-1;i>=0;i--){const k=keys[i],d=descriptors[k];assert(Object.hasOwn(d,'value'),'Accessor in BIR');edges++;stack.push({value:d.value},{token:JSON.stringify(k)+':'});}
  }
  return {sha256:h.digest('hex'),nodes,edges,algorithm:'sorted-own-data-properties/sharing-v1'};
}
function listLength(x){let n=0;while(x?.$==='Con'){assert(++n<=1000000,'Plan list cap');x=x.tail;}assert(x?.$==='Nil','Malformed plan list');return n;}
let state;
export function install(mode){
  assert(MODES.includes(mode),'Bad ablation mode');
  assert(!globalThis.__transportHook,'Duplicate installation');
  const originals=new WeakMap(),ids=new WeakMap();let next=0;
  const identity=x=>{assert(x&&typeof x==='object','Expected object');let id=ids.get(x);if(!id){id=++next;ids.set(x,id);}return id;};
  state={mode,diagnosticOnly:true,events:[],counts:{},widths:[],fingerprintMs:0};
  const mark=(name,extra={})=>{assert(state.events.length<64,'Event cap');state.events.push({name,atMs:performance.now(),cpu:process.cpuUsage(),...extra});};
  const digest=x=>{const start=performance.now(),d=fingerprint(x),elapsedMs=performance.now()-start;state.fingerprintMs+=elapsedMs;return {...d,elapsedMs};};
  globalThis.__transportHook={mark,
    count(name){const key=(state.interval??'outside')+':'+name;state.counts[key]=(state.counts[key]??0)+1;},
    begin(program){
      assert(!state.input,'Expected exactly one optimize call');
      state.input={identity:identity(program),...digest(program)};
      // Ephemeron: the original has no new global strong root. Remove the entry at handoff.
      originals.set(program.codes,program);state.interval='optimizer-validation';mark('optimize-enter');
    },
    widthBegin(program){
      const input=state.rendererInput??state.input;
      assert(input.identity===identity(program),'Width input differs from observed boundary');
      const row={ordinal:state.widths.length+1,inputIdentity:identity(program),inputSha256:input.sha256,startMs:performance.now()};
      state.widths.push(row);mark('width-enter',{ordinal:row.ordinal,inputIdentity:row.inputIdentity});
    },
    widthDone(boundary,result,program){
      const row=state.widths.at(-1);assert(row&&!row.endMs&&row.inputIdentity===identity(program),'Width invocation mismatch');
      row.endMs=performance.now();row.boundary=boundary;row.outputTag=result.$;row.outputIdentity=identity(result);
      mark('width-exit',{ordinal:row.ordinal,boundary,outputTag:row.outputTag});
      row.outputFingerprint=digest(result);
      state.interval=boundary==='optimizer'?'discovery-and-plan':'render';
    },
    planned(plan){state.plan={producerWorkers:listLength(plan.order),consumerWorkers:listLength(plan.consumers)};mark('plan-complete');state.interval='rewrite';},
    original(codes,declarations,constructors,families,type_functions,ending){
      const p=originals.get(codes);assert(p&&p.declarations===declarations&&p.constructors===constructors&&p.families===families&&p.type_functions===type_functions&&p.ending===ending,'Original BIR identity lost');
      state.substitutedIdentity=identity(p);return p;
    },
    backend(program){
      mark('backend-enter');state.interval='link-and-render-validation';
      state.rendererInput={identity:identity(program),...digest(program)};
      const original=originals.get(program.codes);if(original)originals.delete(program.codes);
      if(mode!=='full')assert(state.rendererInput.identity===state.input.identity&&state.rendererInput.sha256===state.input.sha256,'Rewrite-off changed original BIR');
    }
  };
}
export function snapshot(){return state?JSON.parse(JSON.stringify(state)):null;}
export function finish(){
  assert(state?.input&&state.rendererInput,'Missing actual optimizer/renderer boundary');
  assert(state.widths.length===2&&state.widths.every(x=>x.outputTag==='emitter_steps_v1.cps_provider_2_WidthsOk'),'Both required validations must complete');
  if(state.mode==='unchanged')assert(!state.plan,'Unchanged mode planned unexpectedly');
  else assert(state.plan,'Plan continuation not reached');
  globalThis.__transportHook.mark('emit-complete');return snapshot();
}

function prepare(directory){
  directory=resolve(directory);assert(!existsSync(directory),'Fresh suite directory required');verify(FIXED);
  const basePath=ROOT+'/checkpoints/local2039g32c-full/throughput/control-js.request.json';
  const candidatePath=ROOT+'/checkpoints/local2039g32c-full/throughput/candidate-js.request.json';
  const base=json(basePath),candidate=json(candidatePath),manifest=json(OLD+'/manifest.json');
  verify(base.pins);verify(base.inputs);verify(candidate.pins);verify(candidate.inputs);
  assert(JSON.stringify(base.inputs)===JSON.stringify(candidate.inputs)&&base.root===candidate.root,'Frozen workload differs');
  assert(candidate.expectedSelfhostOutput===FULL_OUTPUT,'Historical full output pin differs');
  assert(base.limits.memoryMiB===8192&&base.limits.rssMiB===8192&&base.limits.timeoutMs===600000&&base.limits.pollMs===10,'Guard drift');
  const node=manifest.tools.node,bun=manifest.tools.bun;
  assert(base.node===node,'Pinned runtime differs');
  mkdirSync(directory);
  const original=readFileSync(IMAGE,'utf8'),driverPath=directory+'/transport-driver.mjs';
  let driver=readFileSync(ROOT+'/evals/selfhost_throughput.mjs','utf8').replace(/^#![^\n]*(?:\n|$)/,'');
  for(const f of ['heavy_gate.ts','native_seed_runtime.mjs','checker_core_step_runtime.mjs'])driver=once(driver,"'./"+f+"'",JSON.stringify(ROOT+'/evals/'+f));
  driver='import {install as transportInstall, finish as transportFinish, snapshot as transportSnapshot} from '+JSON.stringify(SELF)+';\n'+driver;
  driver=once(driver,'const request=requestAt(requestPath),output=reportPath+\'.output.mjs\';','const request=requestAt(requestPath),output=reportPath+\'.output.mjs\';transportInstall(request.transport.mode);');
  driver=once(driver,"if(tag(emitted)!=='EmitSuccess')throw Error('Own emission failed');source=emitted.source;","if(tag(emitted)!=='EmitSuccess')throw Error('Own emission failed');report.transport=transportFinish();source=emitted.source;");
  driver=once(driver,"}catch(error){report.status='FAIL';", "}catch(error){report.transport=transportSnapshot();report.status='FAIL';");
  fresh(driverPath,driver);
  const suite={schemaVersion:1,diagnosticOnly:true,accepted:false,directory,node,bun,driverPath,pins:{...FIXED,[SELF]:hash(SELF),[basePath]:hash(basePath),[candidatePath]:hash(candidatePath),[driverPath]:hash(driverPath)},modes:[],limits:base.limits,worker:{stackSizeMb:256,maxOldGenerationSizeMb:6144,maxYoungGenerationSizeMb:128}};
  for(const mode of MODES){
    const changed=instrument(original,{mode}),image=directory+'/transport-'+mode+'.mjs',requestPath=directory+'/transport-'+mode+'.request.json',reportPath=directory+'/transport-'+mode+'.result.json';
    fresh(image,changed.source);save(directory+'/transport-'+mode+'.transform.json',changed.metadata);
    const request={...base,image,transport:{mode},expectedSelfhostOutput:mode==='full'?FULL_OUTPUT:null,pins:{...base.pins,...suite.pins,[image]:hash(image)}};
    save(requestPath,request);suite.modes.push({mode,image,imageSha256:hash(image),requestPath,requestSha256:hash(requestPath),reportPath});
  }
  save(directory+'/transport-suite.json',suite);return suite;
}
async function execute(directory,jit=false){
  const suite=json(resolve(directory,'transport-suite.json'));verify(suite.pins);
  const flags=jit?json(suite.directory+'/transport-jit-options.json').flags:[];
  assert(flags.every(x=>['--trace-opt','--trace-deopt','--trace-turbo-inlining'].includes(x)),'Unexpected JIT flag');
  if(jit)assert(flags.length>0,'No supported JIT events discovered');
  const {runHeavyGate}=await import(ROOT+'/evals/heavy_gate.ts');
  let baseline;
  const outputs=[];
  for(const row of suite.modes){
    assert(!existsSync(row.reportPath),'Fresh result required: '+row.reportPath);
    assert(hash(row.requestPath)===row.requestSha256&&hash(row.image)===row.imageSha256,'Prepared mode drift');
    let requestPath=row.requestPath;
    if(row.mode==='analysis'){
      assert(baseline,'Unchanged baseline must execute first');
      const request=json(requestPath);request.expectedSelfhostOutput=baseline.output.sha256;
      request.pins[baseline.output.path]=baseline.output.sha256;
      requestPath=suite.directory+'/transport-analysis-authorized.request.json';save(requestPath,request);
    }
    const command=[suite.node,...flags,'--experimental-strip-types','--max-old-space-size=6144','--max-semi-space-size=128',suite.driverPath,'--worker','js',requestPath,hash(requestPath),row.reportPath];
    console.log(JSON.stringify({transportMode:row.mode,jit,command}));
    save(suite.directory+'/transport-'+row.mode+'.command.json',{command,limits:suite.limits});
    const guarded=await runHeavyGate(command,{...suite.limits,pollMs:10,label:'G32 diagnostic E02 '+row.mode});
    save(suite.directory+'/transport-'+row.mode+'.guardian.json',guarded);
    assert(guarded.status==='PASS','Guardian failed: '+row.mode);
    const report=json(row.reportPath);assert(report.status==='PASS','Mode failed: '+row.mode);
    assert(hash(report.output.path)===report.output.sha256,'Output drift');
    if(!baseline)baseline=report;
    assert(report.transport.input.sha256===baseline.transport.input.sha256,'Not identical actual BIR across modes');
    if(row.mode==='analysis')assert(report.transport.rendererInput.sha256===baseline.transport.rendererInput.sha256&&report.output.sha256===baseline.output.sha256,'Rewrite-off output differs');
    outputs.push({mode:row.mode,output:report.output,transport:report.transport,phases:report.phases});
  }
  verify(suite.pins);save(suite.directory+'/transport-comparison.json',{status:'PASS_DIAGNOSTIC_ONLY',accepted:false,outputs,limitations:['JS executor only; no native ablation binary built','Plan includes worker body construction; no pure-analysis allocation estimate','Structural hashing and source-entry counters perturb timing; no acceptance claim','Full rewrite renderer consumes transformed BIR, not identical renderer input; unchanged/analysis renderer inputs are identical']});
}

// Parent may request a separate JIT-diagnostic suite. Flags are discovered on the pinned Node,
// never presumed from another V8 release. This command does not run a compiler workload.
function jitOptions(directory){
  const suite=json(resolve(directory,'transport-suite.json'));verify(suite.pins);
  const p=spawnSync(suite.node,['--v8-options'],{encoding:'utf8',maxBuffer:16*1024*1024});
  assert(p.status===0,'Pinned V8 options discovery failed');
  fresh(suite.directory+'/transport-v8-options.txt',p.stdout);
  const flags=['--trace-opt','--trace-deopt','--trace-turbo-inlining'].filter(flag=>p.stdout.includes(flag+' '));
  save(suite.directory+'/transport-jit-options.json',{node:suite.node,nodeSha256:hash(suite.node),flags,command:[suite.node,'--v8-options'],cold:'Fresh process per mode is the only cold compiler scenario provided',warm:'No warm microbenchmark substitute. Repeated complete pipelines in one isolate require a separate explicitly bounded scenario; not silently enabled',note:'Use discovered flags only in separate profiled runs; preserve worker resource limits and guardian. Stdout is raw V8 events, not hardware counts.'});
}
if(process.argv[1]&&resolve(process.argv[1])===SELF){
  const [action,directory]=process.argv.slice(2);assert(directory&&process.argv.length===4,'Usage: bun transport-ablation.mjs --prepare|--execute|--execute-jit|--jit-options FRESH-SUITE-DIR');
  if(action==='--prepare')prepare(directory);
  else if(action==='--execute')await execute(directory);
  else if(action==='--execute-jit')await execute(directory,true);
  else if(action==='--jit-options')jitOptions(directory);
  else throw Error('Unknown command');
}

