function verify(pins){for(const [p,h] of Object.entries(pins))assert(realpathSync(p)===p&&hash(p)===h,'Pin drift: '+p);}
function once(s,a,b){assert(s.split(a).length===2,'Unique source anchor required');return s.replace(a,()=>b);}
const OPTIMIZE=`def optimize(program: BIR.Program) -> BIR.Program:
  match result_widths(program):
    case WidthsFail{message}: program
    case WidthsOk{widths}:
      match program:
        case BIR.Program{+codes, +declarations, +constructors, +families, +type_functions, +end}: optimize_program(codes, declarations, constructors, families, type_functions, end)
`;
const ANALYSIS=`# Diagnostic only: complete the real Plan before returning the same original BIR.
# The generated CPS call graph is checked before canonical native validation.
def transport_analysis_done(planned: Plan, original: BIR.Program) -> BIR.Program:
  match planned:
    case Plan{fresh, producers, order, expansions, consumers}: original

def transport_analysis(+program: BIR.Program) -> BIR.Program:
  match program:
    case BIR.Program{+codes, +declarations, +constructors, +families, +type_functions, +end}:
      +fresh = program_bounds(codes, declarations, end)
      +codes_map = code_map(codes, Map.new(&2, BIR.Code))
      +candidates = candidate_map(codes, Map.new(&2, Cand))
      +plan = Plan{fresh, Map.new(&2, Producer), Nil{}, Map.new(&2, Expansion), Nil{}}
      transport_analysis_done(plan_program(codes, declarations, candidates, codes_map, plan), program)

`;
export function sourceVariant(source,mode){
  assert(sha(source)==='8889717797bcc9757b15af6aead90bc9e510e43ebeac72b4fe7d6738b2b3eaba','Archived canonical transport drift');
  assert(MODES.includes(mode),'Bad mode');
  if(mode==='full')return source;
  const target=mode==='analysis'?'transport_analysis(program)':'program';
  const changed=`def optimize(program: BIR.Program) -> BIR.Program:\n  match result_widths(program):\n    case WidthsFail{message}: program\n    case WidthsOk{widths}: ${target}\n`;
  return once(source,OPTIMIZE,(mode==='analysis'?ANALYSIS:'')+changed);
}
function treePins(directory){
  const pins={};const walk=path=>{for(const entry of readdirSync(path,{withFileTypes:true})){
    const p=resolve(path,entry.name);if(path===directory&&entry.name==='checkpoints')continue;if(entry.isDirectory())walk(p);else if(entry.isFile())pins[p]=hash(p);else assert(!entry.isSymbolicLink(),'Unexpected symlink in diagnostic source tree: '+p);
  }};walk(directory);return pins;
}
async function guarded(command,cwd,report){
